window.__finlexDocLoaded(10043,{"id":10043,"articles":[{"id":1000110,"no":"Overview","heading":"Scope & Key Requirements (Public Summary)","text":"Deals with additional communication in the auditor's report when the auditor considers it necessary to draw users' attention to a matter via an Emphasis of Matter or Other Matter paragraph.","seq":0},{"id":1000111,"no":"ISA 706.8–12","heading":"Emphasis of Matter & Other Matter Paragraphs","text":"Emphasis of Matter (EoM) highlights a matter appropriately presented/disclosed in the FS that is fundamental to users' understanding (without modifying the opinion); Other Matter (OM) communicates a matter relevant to understanding the audit/auditor's responsibilities. Neither replaces KAM (ISA 701) or Going Concern (ISA 570).","seq":1},{"id":1000112,"no":"Official Access","heading":"Official Handbook & Reference Entry","text":"Official source (IAASB 2026 Handbook): https://www.iaasb.org/publications/2026-handbook-international-quality-management-auditing-review-sustainability-and-other-assurance\nStatus: in_force. Detailed paragraph-level summaries and practice notes can be expanded incrementally.\n2026 Handbook Volume: Volume 1 (ISQM 1–2, ISA 200–720)\nLocal Private Full-Text Import: Place the free official 2026 IAASB Handbook PDF in local_pdfs/ and run `python3 scripts/import_private_intl_pdfs.py`.","seq":2}]});
